LANGS = ["en", "ro", "fr", "it", "de", "es", "pt", "nl", "tr"]


def renumber(sections, start_at, bump):
    for s in sections[start_at:]:
        s["heading"] = re.sub(r"^(\d+)\.", lambda m: f"{int(m.group(1)) + bump}.", s["heading"])


def insert(sections, after_index, entries):
    """entries: [(title, html)], numbered right after the section at after_index."""
    base = int(re.match(r"(\d+)\.", sections[after_index]["heading"]).group(1))
    if any(s["heading"].split(". ", 1)[-1] == entries[0][0] for s in sections):
        return False
    renumber(sections, after_index + 1, len(entries))
    for n, (title, html) in enumerate(entries):
        sections.insert(after_index + 1 + n, {"heading": f"{base + 1 + n}. {title}", "html": html})
    return True


def PATCH(data, i):
    lang = LANGS[i]
    priv = data["privacy"]["sections"]
    at = next(n for n, s in enumerate(priv) if re.match(r"\d+\. (Invite Tracking|Invitații|Suivi|Tracciamento|Einladungs|Seguimiento|Rastreio|Uitnodig|Davet)", s["heading"], re.I) or "nvite" in s["heading"])
    if insert(priv, at, [PRIV_L[lang], PRIV_F[lang]]):
        # two references point at sections that moved: the Terms section on third-party bots (20 -> 22) and
        # "Reports and moderation records" of this policy (24 -> 26)
        for sec in priv:
            sec["html"] = sec["html"].replace("See Section 20 of the", "See Section 22 of the").replace("described in Section 24.", "described in Section 26.")
    terms = data["terms"]["sections"]
    at = next(n for n, s in enumerate(terms) if "Discovery" in s["heading"] or "Descoperire" in s["heading"] or "Découverte" in s["heading"])
    insert(terms, at, [TERMS_L[lang], TERMS_F[lang]])
    faq = data["landing"]["faq"]
    for item in FAQ:
        if not any(x.get("q") == item[lang][0] for x in faq):
            faq.append({"q": item[lang][0], "a": item[lang][1]})


